import pandas as pd
import re

# ═══════════════════════════════════════════════════════════════════════
# HUMAN EVALUATION SAMPLING PIPELINE
# 
# Goal: Create annotation sets for human evaluation of real vs synthetic
#       Dutch tenant comments generated by a fine-tuned LLM.
#
# Design:
#   - 80 posts → 80 items (40 real + 40 synthetic)
#   - 8 annotators × 20 items = 160 annotations
#   - Each item seen by exactly 2 annotators
#   - Each annotator sees 10 real + 10 synthetic comments
#   - No post repeated within any annotator's set
#   - Annotators are blind to condition (real vs synthetic)
#
# Metrics evaluated per item:
#   - Fluency    (1-5): grammatical correctness and naturalness
#   - Relevance  (1-5): relevance of comment to the post
#   - Realism    (1-5): plausibility as a real tenant comment
# ═══════════════════════════════════════════════════════════════════════

# ── STEP 1: LOAD DATA ─────────────────────────────────────────────────
# Input: CSV with columns [post, true_comment, generated_comment]
# Source: Fine-tuned Gemma-3-4B-Instruct on Dutch tenant Facebook comments

data = pd.read_csv(
    r"C:\Users\20245179\OneDrive - TU Eindhoven\WP2_Simulation_Tool\Fine Tune gemma\objective\objective_generated_commentsv2.csv"
)

print(f"Raw data: {len(data)} rows")

# ── STEP 2: PREPROCESSING ─────────────────────────────────────────────
# Dutch Facebook data contains anonymized entity tags:
#   <PERSON> → anonymized person names
#   <ORG>    → anonymized organization names
#
# We apply 4 filtering rules:

# Rule 1: Remove rows where true_comment or generated_comment
#         consists ONLY of <PERSON> tags (no meaningful content)
def is_only_person_tags(text):
    """Returns True if text has no content beyond <PERSON> tags."""
    if pd.isna(text):
        return True
    cleaned = re.sub(r'<PERSON>', '', str(text)).strip()
    return cleaned == ''

before = len(data)
data = data[~data['true_comment'].apply(is_only_person_tags)]
data = data[~data['generated_comment'].apply(is_only_person_tags)]
print(f"After removing <PERSON>-only rows: {len(data)} rows (removed {before - len(data)})")

# Rule 2: Remove short/meaningless comments
#         e.g. "Gwen <PERSON>!" or "Nou <PERSON>... ????????"
#         Threshold: at least 5 meaningful words after removing tags/punctuation
def is_meaningful(text, min_words=5):
    """Returns True if text contains at least min_words real words."""
    if pd.isna(text):
        return False
    cleaned = re.sub(r'<PERSON>', '', str(text))
    cleaned = re.sub(r'[^\w\s]', '', cleaned).strip()
    words = [w for w in cleaned.split() if w]
    return len(words) >= min_words

before = len(data)
data = data[data['true_comment'].apply(is_meaningful)]
data = data[data['generated_comment'].apply(is_meaningful)]
print(f"After removing short comments (<5 words): {len(data)} rows (removed {before - len(data)})")

# Rule 3: Replace organization names with <ORG> tag
#         to anonymize Woonbedrijf references
def replace_org(text):
    if pd.isna(text):
        return text
    return re.sub(r'Stichting Woonbedrijf|Woonbedrijf|woonbedrijf|#Woonbedrijf|#woonbedrijf','<ORG>', str(text))


def replace_url(text: str) -> str:
    url_pattern = re.compile(
        r'https?://\S+|www\.\S+',
        re.IGNORECASE
    )
    return url_pattern.sub('<URL>', text)


data['post']              = data['post'].apply(replace_org)
data['true_comment']      = data['true_comment'].apply(replace_org)
data['generated_comment'] = data['generated_comment'].apply(replace_org)
data['post']              = data['post'].apply(replace_url)
data['true_comment']      = data['true_comment'].apply(replace_url)
data['generated_comment'] = data['generated_comment'].apply(replace_url)
print(f"Organization names anonymized → <ORG>")

# Rule 4: Remove duplicate posts (keep first occurrence)
before = len(data)
data = data.drop_duplicates(subset=['post'], keep='first').reset_index(drop=True)
print(f"After removing duplicate posts: {len(data)} rows (removed {before - len(data)})")

print(f"\nFinal dataset: {len(data)} unique posts available")
assert len(data) >= 80, f"Need at least 80 posts, only have {len(data)}"

# ── STEP 3: SAMPLE 80 POSTS ───────────────────────────────────────────
# Randomly sample 80 posts from available 84
# random_state=42 ensures reproducibility

sample = data.sample(n=80, random_state=42).reset_index(drop=True)
sample['pair_id'] = range(1, 81)
print(f"\nSampled 80 posts (pair_id 1–80)")

# ── STEP 4: CREATE 80 ITEMS (40 real + 40 synthetic) ─────────────────
# Each post appears exactly ONCE across all items
# First 40 posts → real comment
# Last  40 posts → synthetic comment
# This ensures no annotator ever sees the same post twice

real_items = sample.iloc[:40][['pair_id', 'post', 'true_comment']].copy()
real_items.columns = ['pair_id', 'post', 'comment']
real_items['condition'] = 'real'

syn_items = sample.iloc[40:][['pair_id', 'post', 'generated_comment']].copy()
syn_items.columns = ['pair_id', 'post', 'comment']
syn_items['condition'] = 'synthetic'

all_items = pd.concat([real_items, syn_items], ignore_index=True)
all_items = all_items.sample(frac=1, random_state=42).reset_index(drop=True)
all_items['item_id'] = range(1, 81)

print(f"Items created: {len(all_items)} (real={len(real_items)}, synthetic={len(syn_items)})")

# ── STEP 5: ASSIGN ITEMS TO ANNOTATOR PAIRS ───────────────────────────
# 80 items split into 4 blocks of 20 items
# Each block assigned to 2 annotators (annotator pair)
# Each block contains 10 real + 10 synthetic items
#
# Block 1 (items  1-20) → annotators 1 & 2
# Block 2 (items 21-40) → annotators 3 & 4
# Block 3 (items 41-60) → annotators 5 & 6
# Block 4 (items 61-80) → annotators 7 & 8

annotator_pairs = [
    (1, 2),
    (3, 4),
    (5, 6),
    (7, 8)
]

annotator_assignments = {}

for block_idx, (ann_a, ann_b) in enumerate(annotator_pairs):
    start = block_idx * 20
    end   = start + 20
    block = all_items.iloc[start:end].copy()

    real_count = len(block[block['condition'] == 'real'])
    syn_count  = len(block[block['condition'] == 'synthetic'])
    print(f"Block {block_idx+1} → annotators ({ann_a},{ann_b}): "
          f"real={real_count}, synthetic={syn_count}")

    for ann_id in [ann_a, ann_b]:
        ann_block = block.copy()
        # Shuffle item order independently per annotator
        ann_block = ann_block.sample(frac=1, random_state=ann_id).reset_index(drop=True)
        ann_block.insert(0, 'annotator_id', ann_id)
        ann_block['item_order'] = range(1, 21)
        annotator_assignments[ann_id] = ann_block

# ── STEP 6: SANITY CHECKS ─────────────────────────────────────────────
master = pd.concat(annotator_assignments.values(), ignore_index=True)

print("\n=== SANITY CHECKS ===")

print(f"\n1. Items per annotator (expect 20):")
print(master.groupby('annotator_id').size().to_string())

print(f"\n2. Unique posts per annotator (expect 20 — no post repeated):")
print(master.groupby('annotator_id')['pair_id'].nunique().to_string())

print(f"\n3. Real/Synthetic per annotator (expect 10 each):")
print(master.groupby(['annotator_id', 'condition']).size().unstack().to_string())

print(f"\n4. Annotators per item (expect 2 for all 80 items):")
per_item = master.groupby('item_id')['annotator_id'].count()
print(per_item.value_counts().to_string())

print(f"\n5. Total annotations: {len(master)} (expect 160)")

# ── STEP 7: SAVE OUTPUTS ──────────────────────────────────────────────
base = r"C:\Users\20245179\OneDrive - TU Eindhoven\WP2_Simulation_Tool\human_evaluation\subsets"

# Annotator CSVs — condition column dropped (blind evaluation)
for ann_id, ann_df in annotator_assignments.items():
    ann_df.drop(columns=['condition']).to_csv(
        f"{base}\\annotator_{ann_id:02d}.csv", index=False
    )

# Master file — private, contains condition labels for analysis
master.to_csv(f"{base}\\master_with_conditions.csv", index=False)

print(f"\n✓ Saved 8 annotator CSVs + master to:\n  {base}")
print(f"\nAnnotator files (blind):  annotator_01.csv … annotator_08.csv")
print(f"Master file (private):    master_with_conditions.csv")